using System;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Linq;using System.Reflection;using System.Runtime.CompilerServices;using System.Text.Json;using HIDMaestro;
internal static class StateCapacityFixture {
 static long checks,sink;static int comparisons;
 static void Check(bool x,string label){checks++;if(!x)throw new InvalidOperationException(label);}
 static HMProfile Profile(string name,int bytes){var t=typeof(HMProfile).Assembly.GetType("HIDMaestro.Internal.ControllerProfile",true)!;var inner=Activator.CreateInstance(t)!;t.GetProperty("Name")!.SetValue(inner,name);t.GetProperty("Id")!.SetValue(inner,name);t.GetProperty("InputReportSize")!.SetValue(inner,bytes);return (HMProfile)typeof(HMProfile).GetConstructor(BindingFlags.NonPublic|BindingFlags.Instance,null,new[]{t},null)!.Invoke(new[]{inner});}
 static bool Same(object? a,object? b)=>a is float af&&b is float bf?BitConverter.SingleToInt32Bits(af)==BitConverter.SingleToInt32Bits(bf):a is double ad&&b is double bd?BitConverter.DoubleToInt64Bits(ad)==BitConverter.DoubleToInt64Bits(bd):Equals(a,b);
 static void Equal(HMGamepadState a,HMGamepadState b){comparisons++;Check(a.Axes is not null&&b.Axes is not null,"missing axes");Check(!ReferenceEquals(a.Axes,b.Axes),"states alias");Check(a.Axes!.Count==6&&b.Axes!.Count==6,"axis count");Check(a.Axes.EnsureCapacity(0)==b.Axes.EnsureCapacity(0),"settled capacity");var aa=a.Axes.ToArray();var bb=b.Axes.ToArray();for(int i=0;i<aa.Length;i++){Check(aa[i].Key==bb[i].Key,"axis insertion order");Check(Same(aa[i].Value,bb[i].Value),"axis float bits");}foreach(var f in typeof(HMGamepadState).GetFields(BindingFlags.Public|BindingFlags.Instance))if(f.Name!="Axes")Check(Same(f.GetValue(a),f.GetValue(b)),"state field:"+f.Name);}
 static string Outcome(bool candidate,bool steam,HMProfile profile,object envelope){try{Program.FixtureState(candidate,steam,profile,envelope);return "accepted";}catch(Exception e){return e.GetType().FullName+":"+e.Message;}}
 static object[] Envelopes(){var rng=new Random(20261015);var result=new object[1024];float[] edge={-1f,1f,0f,-0f,.5f,-.5f,float.Epsilon,-float.Epsilon};for(int i=0;i<result.Length;i++)result[i]=Program.FixtureEnvelope(rng.Next(65536),i<8?edge[i]:(float)(rng.NextDouble()*2-1),(float)(rng.NextDouble()*2-1),(float)(rng.NextDouble()*2-1),(float)(rng.NextDouble()*2-1),(float)rng.NextDouble(),(float)rng.NextDouble(),i%4,i%2,i%2==0,rng.NextDouble()*200-100,rng.NextDouble()*4-2);return result;}
 static void Verify(object[] env){foreach(var (name,bytes,steam) in new[]{("xbox-360-wired",18,false),("xbox-elite-v2",64,false),("xbox-series-xs-bt",64,false),("steam-deck-composite",64,true)}){var p=Profile(name,bytes);foreach(var v in env)Equal(Program.FixtureState(false,steam,p,v),Program.FixtureState(true,steam,p,v));foreach(var c in new[]{false,true}){var first=Program.FixtureState(c,steam,p,env[0]);var retained=first;var original=first.Axes![HMAxis.X];for(int i=1;i<env.Length;i++){var later=Program.FixtureState(c,steam,p,env[i]);Check(!ReferenceEquals(retained.Axes,later.Axes),"fresh state axes reused");later.Axes![HMAxis.X]=123f;Check(Same(retained.Axes![HMAxis.X],original),"previous state changed by later construction");}var copy=first;copy.Axes![HMAxis.X]=456f;Check(Same(retained.Axes![HMAxis.X],456f),"actual SDK struct copy did not preserve alias negative-control");}}
 foreach(var (name,bytes,steam) in new[]{("xbox-360-wired",17,false),("steam-deck-composite",63,true)})Check(Outcome(false,steam,Profile(name,bytes),env[0])==Outcome(true,steam,Profile(name,bytes),env[0]),"profile error mismatch");}
 static List<object> Costs(object[] values){var rows=new List<object>();const int n=100000;foreach(var (name,bytes,steam) in new[]{("xbox-360-wired",18,false),("xbox-elite-v2",64,false),("steam-deck-composite",64,true)}){var profile=Profile(name,bytes);long warmStart=Stopwatch.GetTimestamp();long warmEvents=0;do{for(int k=0;k<4096;k++){var state=Program.FixtureState((k&1)!=0,steam,profile,values[k%values.Length]);sink+=(long)state.Buttons+state.Axes!.Count;}warmEvents+=4096;}while(Stopwatch.GetElapsedTime(warmStart).TotalMilliseconds<400);var rounds=new List<object>();var before=new List<double>();var after=new List<double>();for(int round=0;round<7;round++)for(int order=0;order<2;order++){bool c=order==(round%2);long t=Stopwatch.GetTimestamp();for(int i=0;i<n;i++){var state=Program.FixtureState(c,steam,profile,values[i%values.Length]);sink+=(long)state.Buttons+state.Axes!.Count;}var ns=Stopwatch.GetElapsedTime(t).TotalNanoseconds/n;(c?after:before).Add(ns);rounds.Add(new{round,order,candidate=c,ns});}long Alloc(bool c){long b=GC.GetAllocatedBytesForCurrentThread();for(int i=0;i<n;i++){var state=Program.FixtureState(c,steam,profile,values[i%values.Length]);sink+=(long)state.Buttons+state.Axes!.Count;}return (GC.GetAllocatedBytesForCurrentThread()-b)/n;}var bbytes=Alloc(false);var cbytes=Alloc(true);before.Sort();after.Sort();rows.Add(new{name,beforeNs=before[3],candidateNs=after[3],beforeAllocatedBytes=bbytes,candidateAllocatedBytes=cbytes,eventsPerRound=n,rounds=7,warmEvents,warmElapsedMinimumMs=400,beforeRounds=before,candidateRounds=after,interleavedMeasurements=rounds});}return rows;}
 static int Main(string[] args){try{var values=Envelopes();Verify(values);var costs=args[1]=="benchmark"?Costs(values):null;var result=new{pass=true,checks,builderComparisons=comparisons,retainedSnapshotsVerified=true,axesRemainFreshPerState=true,actualSdkStructAliasNegativeControl=true,profilesAreSyntheticDataOnlyModels=true,costs,runtime=System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription,productHardwareExecuted=false,scope="Complete actual BuildXbox360State/BuildSteamDeckState and same original scalar helpers; HMProfile data-only model built by inert internal constructor, no context/controller/device SDK methods. Cost includes dictionary construction and builder only, not SubmitState/transport/Host process.",sink};File.WriteAllText(args[0],JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true}));return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
